import numpy as np
def bonds(f):
  L=open(f).read().split('\n')[2:];L=[l for l in L if l.strip()];E=[l.split()[0] for l in L];P=np.array([[float(x) for x in l.split()[1:]] for l in L])
  D=np.linalg.norm(P[:,None]-P[None],axis=2)
  r={'H':0.32,'C':0.76,'N':0.71}
  return {(i,j) for i in range(len(P)) for j in range(i+1,len(P)) if E[i] in r and E[j] in r and D[i,j]<1.2*(r[E[i]]+r[E[j]])}
a,b=bonds('init2.xyz'),bonds('c_ff.xyz');print(a^b)
